{

    internal InnerInferenceComponentAutoRollbackConfigurationFactory AutoRollbackConfigurationFactory { get; set; }

    internal InnerInferenceComponentInferenceComponentRollingUpdatePolicyFactory RollingUpdatePolicyFactory { get; set; }

    protected override Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentDeploymentConfig Create()
    {
        var inferenceComponentDeploymentConfigResult = CreateInferenceComponentDeploymentConfig();
        factoryAction?.Invoke(inferenceComponentDeploymentConfigResult);

        return inferenceComponentDeploymentConfigResult;
    }

    private Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentDeploymentConfig CreateInferenceComponentDeploymentConfig()
    {
        var inferenceComponentDeploymentConfigResult = new Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentDeploymentConfig();

        return inferenceComponentDeploymentConfigResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.InferenceComponentTypes.InferenceComponentDeploymentConfig result)
    {
        base.CreateChildren(result);

        result.AutoRollbackConfiguration ??= AutoRollbackConfigurationFactory?.Build();
        result.RollingUpdatePolicy ??= RollingUpdatePolicyFactory?.Build();
    }

} // End Of Class

